import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;
export const durationInFrames = 370;

const COLORS = {
  orange: "#FF6B35",
  cyan: "#00D4FF",
  green: "#00FF94",
  darkBg: "#0A0A0F",
  cardBg: "rgba(255,255,255,0.04)",
  text: "#FFFFFF",
  muted: "#8892A4",
  bg: "#0A0A0F",
};

const TRANSITION = 15;

// ─── Background ───────────────────────────────────────────────────────────────
const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/background.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

// ─── Scene 1: Hero / Logo Reveal ──────────────────────────────────────────────
const SceneHero: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const logoProgress = spring({ frame, fps, delay: 5, config: { damping: 200 } });
  const taglineProgress = spring({ frame, fps, delay: 25, config: { damping: 200 } });
  const subtitleProgress = spring({ frame, fps, delay: 40, config: { damping: 200 } });
  const accentProgress = spring({ frame, fps, delay: 55, config: { damping: 200 } });

  const glowPulse = interpolate(
    Math.sin(frame * 0.08),
    [-1, 1],
    [0.4, 0.8]
  );

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />

      <AbsoluteFill
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            position: "absolute",
            width: 900,
            height: 900,
            borderRadius: "50%",
            background: `radial-gradient(circle, rgba(255,107,53,${glowPulse * logoProgress}) 0%, transparent 70%)`,
            opacity: logoProgress,
            transform: `scale(${interpolate(logoProgress, [0, 1], [0.5, 1])})`,
          }}
        />
      </AbsoluteFill>

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: 0,
          paddingBottom: 160,
        }}
      >
        <div
          style={{
            opacity: logoProgress,
            transform: `scale(${interpolate(logoProgress, [0, 1], [0.7, 1])}) translateY(${interpolate(logoProgress, [0, 1], [40, 0])}px)`,
            marginBottom: 60,
          }}
        >
          <Img
            src={staticFile("assets/apify/Apify Logo white Wordmark.svg")}
            style={{ width: 700, height: "auto" }}
          />
        </div>

        <div
          style={{
            opacity: taglineProgress,
            transform: `translateY(${interpolate(taglineProgress, [0, 1], [50, 0])}px)`,
            fontSize: 96,
            fontWeight: 800,
            color: COLORS.text,
            letterSpacing: "-0.02em",
            textAlign: "center",
            lineHeight: 1.1,
            marginBottom: 40,
          }}
        >
          Extract the{" "}
          <span
            style={{
              background: `linear-gradient(90deg, ${COLORS.orange}, ${COLORS.cyan})`,
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
            }}
          >
            Web's Data
          </span>
        </div>

        <div
          style={{
            opacity: subtitleProgress,
            transform: `translateY(${interpolate(subtitleProgress, [0, 1], [30, 0])}px)`,
            fontSize: 44,
            fontWeight: 400,
            color: COLORS.muted,
            textAlign: "center",
            letterSpacing: "0.01em",
            marginBottom: 64,
          }}
        >
          Turn any website into structured data at scale
        </div>

        <div
          style={{
            opacity: accentProgress,
            transform: `scale(${interpolate(accentProgress, [0, 1], [0.85, 1])})`,
            backgroundColor: "rgba(255,107,53,0.12)",
            border: `2px solid ${COLORS.orange}`,
            borderRadius: 40,
            padding: "20px 56px",
            fontSize: 32,
            fontWeight: 700,
            color: COLORS.orange,
            letterSpacing: "0.12em",
            textTransform: "uppercase",
          }}
        >
          🕷 Web Scraping · Made Simple
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─── Feature items ─────────────────────────────────────────────────────────────
const FEATURES = [
  {
    icon: "🌐",
    title: "Any Website",
    desc: "Scrape static pages, SPAs, and JavaScript-rendered sites",
    color: COLORS.cyan,
  },
  {
    icon: "⚡",
    title: "Massive Scale",
    desc: "Run thousands of parallel scrapers in the cloud",
    color: COLORS.orange,
  },
  {
    icon: "🔄",
    title: "Clean Data",
    desc: "Auto-structured JSON, CSV, Excel output — ready to use",
    color: COLORS.green,
  },
  {
    icon: "🛡",
    title: "Anti-Bot Bypass",
    desc: "Built-in proxy rotation and CAPTCHA solving",
    color: "#A78BFA",
  },
];

const FeatureCard: React.FC<{
  feature: (typeof FEATURES)[number];
  delay: number;
}> = ({ feature, delay }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const progress = spring({ frame, fps, delay, config: { damping: 200 } });

  return (
    <div
      style={{
        opacity: progress,
        transform: `translateY(${interpolate(progress, [0, 1], [60, 0])}px)`,
        backgroundColor: COLORS.cardBg,
        border: `2px solid rgba(255,255,255,0.08)`,
        borderRadius: 28,
        padding: "44px 48px",
        display: "flex",
        flexDirection: "column",
        gap: 20,
        flex: 1,
        position: "relative",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          height: 4,
          background: feature.color,
          borderRadius: "28px 28px 0 0",
          opacity: progress,
        }}
      />

      <div style={{ fontSize: 72 }}>{feature.icon}</div>

      <div
        style={{
          fontSize: 44,
          fontWeight: 700,
          color: COLORS.text,
          letterSpacing: "-0.01em",
        }}
      >
        {feature.title}
      </div>

      <div
        style={{
          fontSize: 32,
          fontWeight: 400,
          color: COLORS.muted,
          lineHeight: 1.4,
        }}
      >
        {feature.desc}
      </div>
    </div>
  );
};

// ─── Scene 2: Features Grid ────────────────────────────────────────────────────
const SceneFeatures: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const titleProgress = spring({ frame, fps, delay: 5, config: { damping: 200 } });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          padding: "0 120px",
          paddingBottom: 100,
          gap: 72,
        }}
      >
        <div
          style={{
            opacity: titleProgress,
            transform: `translateY(${interpolate(titleProgress, [0, 1], [40, 0])}px)`,
            fontSize: 76,
            fontWeight: 800,
            color: COLORS.text,
            letterSpacing: "-0.02em",
            textAlign: "center",
          }}
        >
          Everything you need to{" "}
          <span
            style={{
              background: `linear-gradient(90deg, ${COLORS.orange}, ${COLORS.cyan})`,
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
            }}
          >
            scrape smarter
          </span>
        </div>

        <div
          style={{
            display: "flex",
            gap: 40,
            width: "100%",
          }}
        >
          {FEATURES.map((feature, i) => (
            <FeatureCard key={i} feature={feature} delay={25 + i * 18} />
          ))}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─── Pipeline steps ────────────────────────────────────────────────────────────
const STEPS = [
  { label: "Target URL", icon: "🔗", color: COLORS.cyan },
  { label: "Apify Actor", icon: "🕷", color: COLORS.orange },
  { label: "Parse & Clean", icon: "⚙️", color: "#A78BFA" },
  { label: "Structured Data", icon: "📊", color: COLORS.green },
];

const PipelineStep: React.FC<{
  step: (typeof STEPS)[number];
  index: number;
  delay: number;
  total: number;
}> = ({ step, index, delay, total }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const progress = spring({ frame, fps, delay, config: { damping: 200 } });
  const connectorProgress = spring({ frame, fps, delay: delay + 10, config: { damping: 200 } });

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 0,
      }}
    >
      <div
        style={{
          opacity: progress,
          transform: `scale(${interpolate(progress, [0, 1], [0.6, 1])})`,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 24,
        }}
      >
        <div
          style={{
            width: 160,
            height: 160,
            borderRadius: "50%",
            backgroundColor: `${step.color}18`,
            border: `3px solid ${step.color}`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: 72,
            boxShadow: `0 0 40px ${step.color}40`,
          }}
        >
          {step.icon}
        </div>
        <div
          style={{
            fontSize: 32,
            fontWeight: 700,
            color: COLORS.text,
            textAlign: "center",
            whiteSpace: "nowrap",
          }}
        >
          {step.label}
        </div>
      </div>

      {index < total - 1 && (
        <div
          style={{
            width: 120,
            height: 4,
            marginBottom: 52,
            overflow: "hidden",
            position: "relative",
          }}
        >
          <div
            style={{
              width: `${interpolate(connectorProgress, [0, 1], [0, 100])}%`,
              height: "100%",
              background: `linear-gradient(90deg, ${step.color}, ${STEPS[index + 1].color})`,
              borderRadius: 2,
            }}
          />
          <div
            style={{
              position: "absolute",
              right: 0,
              top: "50%",
              transform: "translateY(-50%)",
              width: 0,
              height: 0,
              borderTop: "12px solid transparent",
              borderBottom: "12px solid transparent",
              borderLeft: `20px solid ${STEPS[index + 1].color}`,
              opacity: connectorProgress,
            }}
          />
        </div>
      )}
    </div>
  );
};

// ─── Scene 3: Pipeline + CTA ───────────────────────────────────────────────────
const ScenePipeline: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const titleProgress = spring({ frame, fps, delay: 5, config: { damping: 200 } });
  const ctaProgress = spring({ frame, fps, delay: 80, config: { damping: 200 } });
  const logoProgress = spring({ frame, fps, delay: 90, config: { damping: 200 } });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: 80,
          paddingBottom: 80,
        }}
      >
        <div
          style={{
            opacity: titleProgress,
            transform: `translateY(${interpolate(titleProgress, [0, 1], [40, 0])}px)`,
            fontSize: 76,
            fontWeight: 800,
            color: COLORS.text,
            letterSpacing: "-0.02em",
            textAlign: "center",
          }}
        >
          From raw web to{" "}
          <span
            style={{
              background: `linear-gradient(90deg, ${COLORS.green}, ${COLORS.cyan})`,
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
            }}
          >
            clean data
          </span>
          {" "}— instantly
        </div>

        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 0,
          }}
        >
          {STEPS.map((step, i) => (
            <PipelineStep
              key={i}
              step={step}
              index={i}
              delay={25 + i * 20}
              total={STEPS.length}
            />
          ))}
        </div>

        <div
          style={{
            opacity: ctaProgress,
            transform: `translateY(${interpolate(ctaProgress, [0, 1], [40, 0])}px)`,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: 32,
          }}
        >
          <div
            style={{
              fontSize: 48,
              fontWeight: 700,
              color: COLORS.text,
              textAlign: "center",
            }}
          >
            Start scraping in minutes with
          </div>

          <div
            style={{
              opacity: logoProgress,
              transform: `scale(${interpolate(logoProgress, [0, 1], [0.85, 1])})`,
            }}
          >
            <Img
              src={staticFile("assets/apify/Apify Logo white Wordmark.svg")}
              style={{ width: 380, height: "auto" }}
            />
          </div>

          <div
            style={{
              backgroundColor: `${COLORS.orange}18`,
              border: `2px solid ${COLORS.orange}`,
              borderRadius: 40,
              padding: "24px 72px",
              fontSize: 36,
              fontWeight: 700,
              color: COLORS.orange,
              letterSpacing: "0.08em",
              opacity: logoProgress,
              transform: `scale(${interpolate(logoProgress, [0, 1], [0.9, 1])})`,
            }}
          >
            apify.com — Free to start
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─── Main Composition ──────────────────────────────────────────────────────────
const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={20}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={100 + TRANSITION}>
        <SceneHero />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={130 + TRANSITION}>
        <SceneFeatures />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={110 + TRANSITION}>
        <ScenePipeline />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={25}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
